python101-files-09.code:
while True:
    command = input("พิมพ์ add/list/quit: ")

    if command == "add":
        task = input("งานใหม่: ")
        with open("todo.txt", "a", encoding="utf-8") as file:
            file.write(task + "\n")
        print("บันทึกงานแล้ว")
    elif command == "list":
        try:
            with open("todo.txt", "r", encoding="utf-8") as file:
                lines = file.readlines()
        except FileNotFoundError:
            lines = []

        if len(lines) == 0:
            print("ยังไม่มีงาน")
        else:
            for line in lines:
                print("- " + line.strip())
    elif command == "quit":
        break
    else:
        print("คำสั่งไม่ถูกต้อง")

